def parse_conditional_expression(num_clauses: int, spec: str) -> int:
    left, right = spec.split('<')
    left_num = int(left)
    right_num = int(right)

    if left_num < right_num:
        return left_num
    else:
        raise ValueError("Conditional expression is not satisfied.")

def parse_absolute_or_percentage(num_clauses: int, spec: str) -> int:
    if '%' in spec:
        percentage = float(spec.rstrip('%'))
        return int(num_clauses * percentage / 100)
    else:
        return int(spec)

if '<' in spec:
    return parse_conditional_expression(num_clauses, spec)
else:
    return parse_absolute_or_percentage(num_clauses, spec)

